#include "placer/multilevel/Clusterer.hpp"
#include <cmath>
namespace placer { Level clusterOneLevel(const Level&fine,const ClusterConfig&cfg){Level c; c.index=fine.index+1; c.fine_to_coarse=std::vector<size_t>(fine.objects.size()); size_t target=(size_t)std::max(1.0,std::ceil((double)fine.movableIds().size()/cfg.coarsen_ratio)); size_t cnt=0; for(size_t i=0;i<fine.objects.size();){auto&o=fine.objects[i]; if(o.fixed||o.is_macro||cnt>=target){LObject co=o; co.children={i}; co.child_offsets[i]={0,0}; (*c.fine_to_coarse)[i]=c.objects.size(); c.objects.push_back(co); ++i; continue;} LObject co; co.name="cluster_"+std::to_string(c.objects.size()); co.x=o.x; co.y=o.y; co.width=o.width; co.height=o.height; co.fixed=false; co.is_macro=false; while(i<fine.objects.size()&&!fine.objects[i].fixed&&!fine.objects[i].is_macro&&cnt<target&&co.children.size()<2){auto&ch=fine.objects[i]; (*c.fine_to_coarse)[i]=c.objects.size(); co.children.push_back(i); co.members.insert(co.members.end(),ch.members.begin(),ch.members.end()); co.child_offsets[i]={ch.cx()-co.cx(),ch.cy()-co.cy()}; co.width+=ch.width; co.height=std::max(co.height,ch.height); ++i; ++cnt;} c.objects.push_back(co);} for(auto&n:fine.nets){LNet cn{n.name,{}}; for(auto&p:n.pins) cn.pins.push_back({(*c.fine_to_coarse)[p.object_id], p.offset_x, p.offset_y}); if(cn.pins.size()>=2)c.nets.push_back(cn);} return c;} std::vector<Level> buildHierarchy(const Level&l0,const ClusterConfig&cfg){std::vector<Level> hs{l0}; while((int)hs.size()<std::min(cfg.max_levels,2) && (int)hs.back().movableIds().size()>cfg.current*cfg.current){hs.push_back(clusterOneLevel(hs.back(),cfg)); if(hs.back().objects.size()>=hs[hs.size()-2].objects.size())break;} return hs;} }
